using System.Windows;
using System.Windows.Controls;
using Fae.Core;

namespace Fae.Desktop;
public partial class MainWindow
{
    private UIElement CanPage()
    {
        var page = CompactPage(1); var body = new Grid(); body.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); body.RowDefinitions.Add(new RowDefinition()); Grid.SetRow(body, 1); page.Children.Add(body);
        var top = new StackPanel(); body.Children.Add(top); var input = Card(top); var row = Row(input); var chip = ChipChoice(row, "can"); var crystal = Input(row, "晶振 / MHz", "30", 90); var sys = Input(row, "主频 / MHz", "150", 90); var instance = Choice(row, "CAN 实例", ["CANA", "CANB"], 0, 90); var source = Choice(row, "CAN 时钟源", ["SYSCLK / 2"], 0, 130);
        row = Row(input); var canClock = Input(row, "CAN 时钟 / MHz", "75", 125); canClock.IsReadOnly = true; var target = Input(row, "波特率 / kbit/s", "500", 130); var sample = Input(row, "采样点 / %", "80", 110); var sjw = Choice(row, "SJW / TQ", ["1", "2", "3", "4"], 0, 80); var driver = new CheckBox { Content = "DriverLib" }; row.Children.Add(driver);
        var actions = Row(input); var clockNote = new TextBlock { VerticalAlignment = VerticalAlignment.Center, FontSize = 11, Foreground = Brush("#64748B"), Margin = new Thickness(8, 0, 0, 0), TextTrimming = TextTrimming.CharacterEllipsis };
        var tabs = new TabControl(); Grid.SetRow(tabs, 1); body.Children.Add(tabs);
        var result = new Grid { Margin = new Thickness(8) }; result.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); result.RowDefinitions.Add(new RowDefinition()); var summary = new TextBlock { Margin = new Thickness(0, 0, 0, 7), TextWrapping = TextWrapping.Wrap, FontSize = 11 }; result.Children.Add(summary);
        var list = new DataGrid(); Column(list, "分频", "Prescaler", 48); Column(list, "TSEG1", "Tseg1", 52); Column(list, "TSEG2", "Tseg2", 52); Column(list, "SJW", "Sjw", 42); Column(list, "TQ", "TotalTq", 42);
        list.Columns.Add(new DataGridTextColumn { Header = "实际 kbit/s", Binding = new System.Windows.Data.Binding("ActualKbps") { StringFormat = "F6" }, Width = 125 }); list.Columns.Add(new DataGridTextColumn { Header = "误差 %", Binding = new System.Windows.Data.Binding("ErrorPercent") { StringFormat = "F6" }, Width = 110 }); list.Columns.Add(new DataGridTextColumn { Header = "采样点 %", Binding = new System.Windows.Data.Binding("SamplePointPercent") { StringFormat = "F3" }, Width = 100 }); Grid.SetRow(list, 1); result.Children.Add(list);
        tabs.Items.Add(new TabItem { Header = "候选时序", Content = result }); var code = CodeTab(tabs); CanInput? last = null;
        void Render()
        {
            if (last == null || list.SelectedItem is not CanTiming timing) return;
            Guard(() => { string text = CanCalculator.GenerateCode(last, timing, driver.IsChecked == true); if (instance.SelectedItem?.ToString() == "CANB") text = text.Replace("ECanaRegs", "ECanbRegs").Replace("CanaRegs", "CanbRegs").Replace("CANA_BASE", "CANB_BASE"); code.Text = text; summary.Text = $"实际 {timing.ActualKbps:F6} kbit/s    误差 {timing.ErrorPercent:F6}%    采样点 {timing.SamplePointPercent:F3}%    {timing.TotalTq} TQ"; _status.Text = "时序已生成"; });
        }
        void Invalidate() { last = null; list.ItemsSource = null; code.Text = ""; summary.Text = "参数已修改，请重新计算。"; }
        void UpdateClock()
        {
            double.TryParse(sys.Text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var main); double.TryParse(crystal.Text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var xtal); canClock.Text = (SelectedChip(chip).CanKind == "eCAN" ? main / 2 : source.SelectedIndex == 1 ? xtal : main).ToString("G", System.Globalization.CultureInfo.InvariantCulture); Invalidate();
        }
        void Configure()
        {
            var c = SelectedChip(chip); driver.IsEnabled = c.DriverLib; if (!c.DriverLib) driver.IsChecked = false; source.ItemsSource = c.CanKind == "eCAN" ? new[] { "SYSCLK / 2" } : new[] { "SYSCLK", "外部晶振" }; source.SelectedIndex = 0; instance.ItemsSource = c.Id is "335" or "0049" ? new[] { "CANA", "CANB" } : new[] { "CANA" }; instance.SelectedIndex = 0; sys.Text = c.Id switch { "335" => "150", "035" => "60", "0039" => "120", _ => "100" }; crystal.Text = c.Id switch { "335" => "30", "0049" => "20", _ => "10" }; clockNote.Text = c.CanKind + " · 时钟源须与工程一致"; UpdateClock();
        }
        void Calculate() => Guard(() => { last = new CanInput(SelectedChip(chip).Id, Number(crystal), Number(sys), Number(canClock), Number(target), Number(sample), int.Parse(sjw.SelectedItem?.ToString() ?? "1")); var timings = CanCalculator.Calculate(last); list.ItemsSource = timings; if (timings.Count > 0) list.SelectedIndex = 0; else { code.Text = ""; summary.Text = "没有合法时序。"; } });
        var calculate = ActionButton(actions, "计算并生成代码", Calculate, true); calculate.Tag = "layout-required"; actions.Children.Add(clockNote);
        list.SelectionChanged += (_, _) => Render(); driver.Checked += (_, _) => Render(); driver.Unchecked += (_, _) => Render(); instance.SelectionChanged += (_, _) => Render(); chip.SelectionChanged += (_, _) => Configure(); source.SelectionChanged += (_, _) => UpdateClock(); sys.TextChanged += (_, _) => UpdateClock(); crystal.TextChanged += (_, _) => UpdateClock(); target.TextChanged += (_, _) => Invalidate(); sample.TextChanged += (_, _) => Invalidate(); sjw.SelectionChanged += (_, _) => Invalidate();
        Configure(); Calculate(); _smokeChecks.Add(() => { int original = chip.SelectedIndex; for (int i = 0; i < Chips.All.Length; i++) { chip.SelectedIndex = i; Calculate(); if (string.IsNullOrEmpty(code.Text)) throw new InvalidOperationException("CAN位域代码自检失败。"); if (Chips.All[i].DriverLib) { driver.IsChecked = true; if (!code.Text.Contains("CAN_setBitTiming")) throw new InvalidOperationException("CAN DriverLib自检失败。"); driver.IsChecked = false; } } chip.SelectedIndex = original; Calculate(); tabs.SelectedIndex = 1; UpdateLayout(); ValidateVisibleLayout(); tabs.SelectedIndex = 0; }); return page;
    }

    private UIElement PwmPage()
    {
        var page = CompactPage(2); var body = new Grid(); body.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); body.RowDefinitions.Add(new RowDefinition()); Grid.SetRow(body, 1); page.Children.Add(body); var top = new StackPanel(); body.Children.Add(top); var input = Card(top); var row = Row(input); var chip = ChipChoice(row, "pwm"); var sys = Input(row, "主频 / MHz", "150", 95); var instance = Choice(row, "PWM 实例", Enumerable.Range(1, 6).Select(i => "ePWM" + i), 0, 100); var mode = Choice(row, "计数模式", ["向上计数", "向下计数", "上下计数"], 2, 115); var peripheral = Choice(row, "EPWMCLK分频", ["1", "2"], 0, 115);
        row = Row(input); var high = Choice(row, "HSPCLKDIV分频", ["1", "2", "4", "6", "8", "10", "12", "14"], 0, 120); var divider = Choice(row, "CLKDIV分频", ["1", "2", "4", "8", "16", "32", "64", "128"], 0, 110); var direction = Choice(row, "计算方向", ["频率 → 周期", "周期 → 频率"], 0, 130); var target = Input(row, "目标频率 / Hz", "20000", 120); var period = Input(row, "TBPRD", "3750", 95);
        var actions = Row(input); var driver = new CheckBox { Content = "DriverLib" }; actions.Children.Add(driver);
        var tabs = new TabControl(); Grid.SetRow(tabs, 1); body.Children.Add(tabs); var output = new StackPanel { Margin = new Thickness(12) }; var resultText = new TextBlock { FontSize = 18, LineHeight = 30, TextWrapping = TextWrapping.Wrap }; output.Children.Add(resultText); Note(output, "TBCLK = SYSCLK ÷ EPWMCLK分频 ÷ HSPCLKDIV ÷ CLKDIV\n向上/向下：f = TBCLK/(TBPRD+1)；上下：f = TBCLK/(2×TBPRD)。"); tabs.Items.Add(new TabItem { Header = "计算结果", Content = output }); var code = CodeTab(tabs); PwmInput? last = null; PwmResult? result = null;
        void Render() { if (last == null || result == null) return; Guard(() => { string text = PwmCalculator.GenerateCode(last, result, driver.IsChecked == true); int n = instance.SelectedIndex + 1; code.Text = text.Replace("EPwm1Regs", $"EPwm{n}Regs").Replace("EPWM1_BASE", $"EPWM{n}_BASE"); }); }
        void Invalidate() { last = null; result = null; code.Text = ""; resultText.Text = "参数已修改，请重新计算。"; }
        void Configure() { var c = SelectedChip(chip); driver.IsEnabled = c.DriverLib; if (!c.DriverLib) driver.IsChecked = false; sys.Text = c.Id switch { "335" => "150", "035" => "60", "0039" => "120", _ => "100" }; peripheral.ItemsSource = c.Id is "035" or "335" ? new[] { "1" } : new[] { "1", "2" }; peripheral.SelectedIndex = c.Id == "0039" ? 1 : 0; instance.ItemsSource = Enumerable.Range(1, c.Id == "335" ? 6 : c.Id == "035" ? 7 : 8).Select(n => "ePWM" + n).ToArray(); instance.SelectedIndex = 0; Invalidate(); }
        void Calculate() => Guard(() => { last = new PwmInput(SelectedChip(chip).Id, Number(sys), int.Parse(peripheral.SelectedItem?.ToString() ?? "1"), int.Parse(high.SelectedItem?.ToString() ?? "1"), int.Parse(divider.SelectedItem?.ToString() ?? "1"), mode.SelectedIndex switch { 0 => "up", 1 => "down", _ => "updown" }, direction.SelectedIndex == 0 ? Number(target) : 0, direction.SelectedIndex == 1 ? Integer(period) : null); result = PwmCalculator.Calculate(last); resultText.Text = $"TBCLK    {result.TbClockHz:N0} Hz\nTBPRD    {result.Period}\n实际频率  {result.ActualHz:F6} Hz\n目标误差  {result.ErrorPercent:F6}%"; Render(); _status.Text = "PWM参数已生成"; });
        var calculate = ActionButton(actions, "计算并生成代码", Calculate, true); calculate.Tag = "layout-required";
        chip.SelectionChanged += (_, _) => Configure(); foreach (var c in new[] { mode, peripheral, high, divider, direction }) c.SelectionChanged += (_, _) => { target.IsEnabled = direction.SelectedIndex == 0; period.IsEnabled = direction.SelectedIndex == 1; Invalidate(); }; foreach (var t in new[] { sys, target, period }) t.TextChanged += (_, _) => Invalidate(); driver.Checked += (_, _) => Render(); driver.Unchecked += (_, _) => Render(); instance.SelectionChanged += (_, _) => Render();
        period.IsEnabled = false; Configure(); Calculate(); _smokeChecks.Add(() => { int original = chip.SelectedIndex; for (int i = 0; i < Chips.All.Length; i++) { chip.SelectedIndex = i; Calculate(); if (string.IsNullOrEmpty(code.Text)) throw new InvalidOperationException("PWM位域代码自检失败。"); if (Chips.All[i].DriverLib) { driver.IsChecked = true; if (!code.Text.Contains("EPWM_")) throw new InvalidOperationException("PWM DriverLib自检失败。"); driver.IsChecked = false; } } chip.SelectedIndex = original; Calculate(); tabs.SelectedIndex = 1; UpdateLayout(); ValidateVisibleLayout(); tabs.SelectedIndex = 0; }); return page;
    }
}
